parameters.jsCode:
// El prompt de marca vive en n8n/prompts/sistema-marca.md.
// Se pega aquí para que el workflow sea autocontenido al importarlo.
// Al cambiar el fichero, actualiza también este nodo.
const sistema = `Eres el redactor de Modo Guerrero...`;
return [{ json: { sistema } }];

// Validación antes de tocar la base de datos.
//
// output_config.format ya garantiza la forma del JSON, pero no las reglas de
// negocio: longitudes que Google trunca, y sobre todo el vocabulario prohibido
// que puede costar la cuenta publicitaria.

const r = $input.first().json;

// Los clasificadores pueden rechazar la petición con HTTP 200.
if (r.stop_reason === 'refusal') {
  throw new Error('Claude ha rechazado la peticion: ' + (r.stop_details?.category ?? 'sin categoria'));
}

const texto = r.content?.find((b) => b.type === 'text')?.text;
if (!texto) throw new Error('Respuesta sin bloque de texto');

let a;
try {
  a = JSON.parse(texto);
} catch {
  throw new Error('La respuesta no es JSON valido pese al esquema');
}

// Vocabulario que no puede aparecer. No es preferencia de estilo: una
// afirmacion fisiologica o un termino explicito puede costar la cuenta de
// AdSense, que es lo que financia el proyecto.
const PROHIBIDO = [
  'testosterona', 'dopamina', 'hormona', 'neurotransmisor',
  'curar', 'curacion', 'sanar', 'superpoder', 'piedra filosofal',
  'garantizado', 'garantizamos',
];

const cuerpo = (a.titulo + ' ' + a.meta_description + ' ' + a.contenido_md).toLowerCase();
const encontrados = PROHIBIDO.filter((p) => cuerpo.includes(p));

// Slug desde el titulo: minusculas, sin acentos, sin signos.
const slug = a.titulo
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 80);

const palabras = a.contenido_md.trim().split(/\s+/).length;

return [{
  json: {
    ...a,
    slug,
    tiempo_lectura: Math.max(1, Math.round(palabras / 200)),
    _palabras: palabras,
    // Avisos, no errores: los decide una persona en Telegram.
    _avisos: [
      ...(encontrados.length ? ['Vocabulario prohibido: ' + encontrados.join(', ')] : []),
      ...(a.titulo.length > 65 ? ['Titulo de ' + a.titulo.length + ' caracteres (Google trunca en ~65)'] : []),
      ...(a.meta_description.length > 155 ? ['Meta description de ' + a.meta_description.length + ' caracteres (se trunca en ~155)'] : []),
      ...(palabras < 900 ? ['Solo ' + palabras + ' palabras'] : []),
      ...(/^#\s/m.test(a.contenido_md) ? ['El markdown lleva un H1: saldra duplicado con el titulo'] : []),
    ],
  },
}];

